MAX_X = 10**6

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    Q = data[0]
    queries = data[1:1 + Q]

    spf = [0] * (MAX_X + 1)
    for i in range(2, MAX_X + 1):
        if spf[i] == 0:
            spf[i] = i
            if i * i <= MAX_X:
                for j in range(i * i, MAX_X + 1, i):
                    if spf[j] == 0:
                        spf[j] = i

    candidates = []
    for x in range(2, MAX_X + 1):
        n = x
        cnt = 0
        last = 0
        while n > 1:
            p = spf[n]
            if p != last:
                cnt += 1
                last = p
            n //= p
        if cnt == 2:
            candidates.append(x)

    out = []
    br = bisect_right

    for a in queries:
        r = isqrt(a)
        x = candidates[br(candidates, r) - 1]
        out.append(str(x * x))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()

