import sys
from collections import deque

def main():
    input = sys.stdin.readline

    H, W = map(int, input().split())
    S = [input().strip() for _ in range(H)]
    A, B, C, D = map(int, input().split())

    sr, sc = A - 1, B - 1
    tr, tc = C - 1, D - 1

    N = H * W
    INF = 10 ** 9
    dist = [INF] * N

    start = sr * W + sc
    goal = tr * W + tc
    dist[start] = 0

    dq = deque([start])
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while dq:
        v = dq.popleft()
        d = dist[v]

        if v == goal:
            break

        r = v // W
        c = v % W

        # Move to adjacent road cell with cost 0
        if r > 0:
            nv = v - W
            if S[r - 1][c] == '.':
                if d < dist[nv]:
                    dist[nv] = d
                    dq.appendleft(nv)

        if r + 1 < H:
            nv = v + W
            if S[r + 1][c] == '.':
                if d < dist[nv]:
                    dist[nv] = d
                    dq.appendleft(nv)

        if c > 0:
            nv = v - 1
            if S[r][c - 1] == '.':
                if d < dist[nv]:
                    dist[nv] = d
                    dq.appendleft(nv)

        if c + 1 < W:
            nv = v + 1
            if S[r][c + 1] == '.':
                if d < dist[nv]:
                    dist[nv] = d
                    dq.appendleft(nv)

        # Perform front kick with cost 1
        for dr, dc in dirs:
            nr = r + dr
            nc = c + dc
            if 0 <= nr < H and 0 <= nc < W:
                nv = nr * W + nc
                nd = d + 1
                if nd < dist[nv]:
                    dist[nv] = nd
                    dq.append(nv)

            nr = r + 2 * dr
            nc = c + 2 * dc
            if 0 <= nr < H and 0 <= nc < W:
                nv = nr * W + nc
                nd = d + 1
                if nd < dist[nv]:
                    dist[nv] = nd
                    dq.append(nv)

    print(dist[goal])

if __name__ == "__main__":
    main()

